"""Literal original connectionSide and CSS in a fixed example-only parent."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download'
src=(r/'docs/replica/source/original.js').read_text().splitlines();defs='\n'.join(s for s in src if s.startswith(('const esc=','const icons=','const icon=','const t=','const pill=','const field=','function connectionSide(')))
cases=[dict(id=f'{lang}-{side}-{width}-{int(connected)}',lang=lang,side=side,width=width,connected=connected)for width in [328,338,409,442,522]for lang in ['ko','en']for side in ['source','target']for connected in [False,True]]
(o/'connectionpanel-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
html='''<!doctype html><meta charset="utf-8"><title>ConnectionPanel · original isolation</title><link rel="stylesheet" href="connectionpanel-original.css"><style>body{min-width:960px}.fixture{position:absolute;left:30px;top:30px}.fixture:not(:first-child){visibility:hidden}#panel-record{position:fixed;left:600px;top:30px}</style><button id="panel-record">Record ConnectionPanel</button><div id="fixtures"></div><script>let lang='ko',state={source:{host:'source.example.invalid',port:'1433',db:'migration_sample',user:'demo_reader'},target:{host:'target.example.invalid',port:'1433',db:'migration_sample',user:'demo_reader'},connected:false},events=[];'''+defs+'\nconst cases='+json.dumps(cases)+''';for(const c of cases){lang=c.lang;state.connected=c.connected;const f=document.createElement('section');f.className='fixture';f.dataset.id=c.id;f.style.width=c.width+'px';f.innerHTML=connectionSide(c.side);if(c.id!==cases[0].id)f.setAttribute('aria-hidden','true');document.getElementById('fixtures').append(f)}function read(){return [...document.querySelectorAll('.fixture')].map(f=>{const e=f.firstElementChild,r=e.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}},h=e.querySelector('.form-head');return{id:f.dataset.id,width:r.width,height:r.height,shadow:getComputedStyle(e).boxShadow,header:box(h),mark:box(h.querySelector('.role-mark')),icon:box(h.querySelector('.svg')),titles:box(h.children[1]),title:box(h.querySelector('h2')),subtitle:box(h.querySelector('small')),status:box(h.querySelector('.pill')),statusText:h.querySelector('.pill').textContent,serverRow:box(e.querySelector('.field-row')),fields:[...e.querySelectorAll('.field')].map(d=>({box:box(d),label:box(d.querySelector('label')),input:box(d.querySelector('input')),hint:d.querySelector('small')?box(d.querySelector('small')):null,labelText:d.querySelector('label').textContent,value:d.querySelector('input').value,disabled:d.querySelector('input').disabled}))}})}document.getElementById('panel-record').onclick=async()=>{await document.fonts.ready;const response=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:read(),events})});if(!response.ok)throw Error('Evidence failed');document.getElementById('panel-record').textContent='ConnectionPanel recorded'};document.addEventListener('input',e=>{if(e.target.closest('.fixture')?.getAttribute('aria-hidden')==='true')return;if(e.target.closest('.field'))events.push({key:e.target.dataset.field,value:e.target.value,trusted:e.isTrusted})});</script>'''
(o/'connectionpanel.html').write_text(html)
for p in [o/'connectionpanel-cases.json',r/'docs/replica/source/connectionpanel-cases.json']:p.write_text(json.dumps(cases,indent=2)+'\n')
print(len(cases),'original connection panel cases prepared')
